using System.Linq;
using RimWorld;
using Verse;
using RimMandrake.HugeThings;

namespace RimMandrake.TitanicCreatures
{
    /// <summary>
    /// The one place tier is computed. Everything else in the mod (comp
    /// auto-attach, the wake processor, the yield curve, the corpse-site
    /// conversion, LargePawnsBridge) calls through here rather than reading
    /// bodySize or the modExtension itself. Comp attachment is conservative;
    /// event eligibility uses lineage, spacing uses supported stages, and runtime uses actual size.
    /// </summary>
    public static class TitanicTierUtility
    {
        private static RM_TitanicTierDef cachedThresholds;
        private static readonly RM_TitanicTierDef customThresholds = new RM_TitanicTierDef { defName = "RM_TitanicTiers_ModSettings" };

        /// <summary>
        /// The ladder in force: the player's custom tiers (Mod Settings, giant animals on, custom tiers on, and strictly rising),
        /// else the shipped RM_TitanicTierDef. Which races carry the wake comp and the Large Pawns rows are decided from this at
        /// startup, so a change that moves a race across T1 needs a restart (the settings label says so); runtime tiers follow
        /// it at once.
        /// </summary>
        public static RM_TitanicTierDef Thresholds
        {
            get
            {
                if (RM_HugeThingsSettings.TierThresholdsCustomActive
                    && RM_TitanicKernel.ThresholdsValid(RM_HugeThingsSettings.tierT1MinBodySize, RM_HugeThingsSettings.tierT2MinBodySize,
                                                        RM_HugeThingsSettings.tierT3MinBodySize))
                {
                    customThresholds.t1MinBodySize = RM_HugeThingsSettings.tierT1MinBodySize;
                    customThresholds.t2MinBodySize = RM_HugeThingsSettings.tierT2MinBodySize;
                    customThresholds.t3MinBodySize = RM_HugeThingsSettings.tierT3MinBodySize;
                    return customThresholds;
                }
                return ShippedThresholds;
            }
        }

        /// <summary>The shipped ladder, Defs/TitanicTierDefs/RM_TitanicTierDef.xml.</summary>
        public static RM_TitanicTierDef ShippedThresholds
        {
            get
            {
                if (cachedThresholds == null)
                {
                    cachedThresholds = DefDatabase<RM_TitanicTierDef>.AllDefsListForReading.FirstOrDefault();
                    if (cachedThresholds == null)
                    {
                        Log.Error("[RimMandrake.TitanicCreatures] No RM_TitanicTierDef found - " +
                                  "Defs/TitanicTierDefs/RM_TitanicTierDef.xml is missing or failed to " +
                                  "load. Falling back to hardcoded defaults (4/8/20); fix the XML.");
                        cachedThresholds = new RM_TitanicTierDef();
                    }
                }
                return cachedThresholds;
            }
        }

        /// <summary>RM_TitanicExtension.forceEnabled as the kernel's tri-state.</summary>
        public static int ForceOf(RM_TitanicExtension ext)
        {
            if (ext == null || ext.forceEnabled == null) return RM_TitanicKernel.ForceAuto;
            return ext.forceEnabled == true ? RM_TitanicKernel.ForceIn : RM_TitanicKernel.ForceOut;
        }

        /// <summary>
        /// Def-level qualification check: could ANY pawn of this race ever be
        /// tiered? Used only to decide whether to auto-attach CompTitanicWake
        /// at def-load time (a lifestage/gene swelling a borderline race past
        /// the floor at runtime must not require the comp to already be
        /// present, so this checks the race's base bodySize, not any one
        /// pawn's current BodySize).
        /// </summary>
        public static bool DefQualifies(ThingDef raceDef)
        {
            if (raceDef?.race == null)
            {
                return false;
            }
            // TITAN_WAKE_FIXES_1 (B3.18 / C3.4): Pawn.BodySize = CurLifeStage.bodySizeFactor * baseBodySize, so qualify on the base times
            // the largest life-stage factor; a race whose adult stage swells past T1 must carry the comp from the start.
            float maxFactor = 1f;
            if (raceDef.race.lifeStageAges != null)
                foreach (LifeStageAge a in raceDef.race.lifeStageAges)
                    if (a?.def != null && a.def.bodySizeFactor > maxFactor) maxFactor = a.def.bodySizeFactor;
            return RM_TitanicKernel.DefQualifies(raceDef.race.baseBodySize, maxFactor, Thresholds.t1MinBodySize,
                ForceOf(raceDef.GetModExtension<RM_TitanicExtension>()));
        }

        /// <summary>TITAN_CAMPS_SCAVENGERS_EVENTS_1: the tier a race's grown adult reaches (base size times its largest life-stage
        /// factor) - what decides whether a race is a titan for the titan event and a non-titan for the scavenger draw.</summary>
        public static TitanicTier AdultTier(ThingDef raceDef)
        {
            if (raceDef?.race == null) return TitanicTier.None;
            float maxFactor = 1f;
            if (raceDef.race.lifeStageAges != null)
                foreach (LifeStageAge a in raceDef.race.lifeStageAges)
                    if (a?.def != null && a.def.bodySizeFactor > maxFactor) maxFactor = a.def.bodySizeFactor;
            RM_TitanicTierDef t = Thresholds;
            return (TitanicTier)RM_TitanicKernel.TierFor(raceDef.race.baseBodySize * maxFactor, t.t1MinBodySize, t.t2MinBodySize,
                t.t3MinBodySize, ForceOf(raceDef.GetModExtension<RM_TitanicExtension>()));
        }

        /// <summary>Passage spacing only: the largest supported stage of this race. Lineage eligibility stays on AdultTier
        /// ("Calves are ok"). Incomplete/malformed stage data cannot justify relaxing spacing, so it falls back to AdultTier.
        /// Read the current ladder every time; neither tiers nor stage factors are cached. Comp attachment stays separate.</summary>
        public static TitanicTier SpacingTier(ThingDef raceDef)
        {
            if (raceDef?.race == null) return TitanicTier.None;
            float maxFactor = RM_TitanicKernel.MaxSupportedLifeStageFactor(
                raceDef.race.lifeStageAges?.Select(a => a?.def == null ? float.NaN : a.def.bodySizeFactor));
            if (!RM_TitanicKernel.Finite(maxFactor)) return AdultTier(raceDef);
            RM_TitanicTierDef t = Thresholds;
            return (TitanicTier)RM_TitanicKernel.TierFor(raceDef.race.baseBodySize * maxFactor, t.t1MinBodySize,
                t.t2MinBodySize, t.t3MinBodySize, ForceOf(raceDef.GetModExtension<RM_TitanicExtension>()));
        }

        /// <summary>
        /// The runtime tier for one pawn right now - the authority every
        /// other system in this mod reads.
        /// </summary>
        public static TitanicTier GetTier(Pawn pawn)
        {
            if (pawn?.RaceProps == null)
            {
                return TitanicTier.None;
            }
            // Core BodySize is current-stage factor times base size. Loaded postfixes can modify that getter
            // (VEF adds its cached offset and floors at 0.05); read the actual property, never substitute a formula.
            // Def-level event spacing cannot forecast external runtime modifiers. The L1 needs-null fixture exercises
            // VEF's default-cache branch only, not generated-pawn gene/hediff modifier computation.
            RM_TitanicTierDef t = Thresholds;
            return (TitanicTier)RM_TitanicKernel.TierFor(pawn.BodySize, t.t1MinBodySize, t.t2MinBodySize, t.t3MinBodySize,
                ForceOf(pawn.def.GetModExtension<RM_TitanicExtension>()));
        }
    }
}
using System.Collections.Generic;
using System.Linq;
using RimWorld;
using UnityEngine;
using Verse;
using Verse.AI;
using Verse.AI.Group;
using RimMandrake.HugeThings;

namespace RimMandrake.TitanicCreatures
{
    /// <summary>
    /// TITAN_CAMPS_SCAVENGERS_EVENTS_1, card #5 (owner 2026-09-09): "Titans roam only where the rosters home them; anywhere else
    /// they arrive as scripted events/quests with warning (footfall tremors first). Wake damage applies to any structure including
    /// the player's - that is the point."
    ///
    /// The incident only SCHEDULES: it picks a titan from this map biome's own hints (its RM_TitanPassageExtension passage list,
    /// else its own roster; sea giants only on sea maps, land giants only on land; owner by card 2026-10-21), sends the tremor
    /// letter, and hands the passage to MapComponent_TitanPassages, which shakes the camera with growing force through the
    /// warning hours and then walks the titan across the map edge to edge (vanilla LordJob_ExitMapNear, the herd-migration
    /// shape). The wake does the rest. No race or biome is named in code: the biome data decides who comes.
    /// </summary>
    public class IncidentWorker_TitanPassage : IncidentWorker
    {
        protected override bool CanFireNowSub(IncidentParms parms)
        {
            Map map = parms.target as Map;
            if (map == null || !RM_HugeThingsSettings.TitanEventsActive) return false;
            MapComponent_TitanPassages comp = map.GetComponent<MapComponent_TitanPassages>();
            if (comp == null || comp.HasPending) return false;
            return TitanPassageUtility.TryFindTitanKind(map, out _) && TitanPassageUtility.TryFindStartAndEnd(map, out _, out _);
        }

        protected override bool TryExecuteWorker(IncidentParms parms)
        {
            Map map = (Map)parms.target;
            if (!TitanPassageUtility.TryFindTitanKind(map, out PawnKindDef kind)) return false;
            if (!TitanPassageUtility.TryFindStartAndEnd(map, out IntVec3 start, out IntVec3 end)) return false;
            MapComponent_TitanPassages comp = map.GetComponent<MapComponent_TitanPassages>();
            if (comp == null) return false;
            comp.Schedule(kind, start, end, RM_TitanicKernel.WarningTicks(RM_HugeThingsSettings.titanEventWarningHours));
            SendStandardLetter("RM_TitanPassage_TremorLabel".Translate(), "RM_TitanPassage_TremorText".Translate(
                    TitanPassageUtility.EdgeName(map, start)), LetterDefOf.ThreatSmall, parms, new TargetInfo(start, map));
            return true;
        }
    }

    public static class TitanPassageUtility
    {
        public const string SeabedLayerDefName = "RM_SeabedLayer";
        public const string SeabedFloorExtensionName = "RM_SeabedFloorExtension";

        /// <summary>The 2026-10-21 card's gate, per kind: RM_TitanicKernel.TitanEventEligible over the live biome commonalities.
        /// A calf kind qualifies by lineage ("Calves are ok"); only supported T3 stages trigger the existing-T3 veto.</summary>
        public static bool Eligible(PawnKindDef k, Map map, bool t3OnMap)
        {
            if (k?.race?.race == null || map == null || !k.RaceProps.Animal || k.RaceProps.Dryad) return false;
            if (k.race.GetModExtension<RM_TitanicExtension>()?.harnessOnly == true) return false;
            int tier = (int)TitanicTierUtility.AdultTier(k.race);
            if (tier < RM_TitanicKernel.T2) return false;
            bool optedOut = map.Biomes.Any(b => b?.GetModExtension<RM_TitanPassageExtension>()?.none == true);
            bool hasList = false, onList = false;
            foreach (BiomeDef b in map.Biomes)
            {
                List<PawnKindDef> list = b?.GetModExtension<RM_TitanPassageExtension>()?.passers;
                if (list == null || list.Count == 0) continue;
                hasList = true;
                if (list.Contains(k)) onList = true;
            }
            bool here = map.Biomes.Any(b => b.CommonalityOfAnimal(k) > 0f);
            bool season = map.mapTemperature.SeasonAndOutdoorTemperatureAcceptableFor(k.race);
            return RM_TitanicKernel.TitanEventEligible(tier, (int)TitanicTierUtility.SpacingTier(k.race), optedOut, IsSeaCreature(k), IsSeaMap(map), hasList, onList, here,
                season, t3OnMap);
        }

        /// <summary>A sea biome: a water biome (Grey Sea, Twilight Sea, the Scald, the Chill...) or a seabed floor, whose cast is
        /// its sea's (RM_SeabedFloorLife copies it at startup). The floor test is by extension type name on purpose: this
        /// assembly must not depend on DivingInteraction.</summary>
        public static bool IsSeaBiome(BiomeDef b)
        {
            if (b == null) return false;
            if (b.isWaterBiome) return true;
            if (b.modExtensions != null)
                foreach (DefModExtension e in b.modExtensions)
                    if (e != null && e.GetType().Name == SeabedFloorExtensionName) return true;
            return false;
        }

        /// <summary>A sea map: its own biome is a sea biome, or it lies on the seabed planet layer (name test, as
        /// RM_SurfaceHome.IsSeabedMap).</summary>
        public static bool IsSeaMap(Map map)
        {
            if (map == null) return false;
            if (map.Tile.Valid && map.Tile.Layer?.Def?.defName == SeabedLayerDefName) return true;
            return IsSeaBiome(map.Biome);
        }

        private static Dictionary<PawnKindDef, bool> seaCache;

        /// <summary>A sea creature: homed in at least one biome, and only ever in sea biomes. Cached per kind (rosters are fixed
        /// after def load).</summary>
        public static bool IsSeaCreature(PawnKindDef k)
        {
            if (k == null) return false;
            if (seaCache == null) seaCache = new Dictionary<PawnKindDef, bool>();
            if (seaCache.TryGetValue(k, out bool v)) return v;
            int sea = 0, land = 0;
            foreach (BiomeDef b in DefDatabase<BiomeDef>.AllDefsListForReading)
            {
                if (b.CommonalityOfAnimal(k) <= 0f) continue;
                if (IsSeaBiome(b)) sea++; else land++;
            }
            v = RM_TitanicKernel.IsSeaCreature(sea, land);
            seaCache[k] = v;
            return v;
        }

        public static bool T3OnMap(Map map)
        {
            return map.mapPawns.AllPawnsSpawned.Any(p => !p.Dead && TitanicTierUtility.GetTier(p) == TitanicTier.T3);
        }

        public static bool TryFindTitanKind(Map map, out PawnKindDef kind)
        {
            bool t3 = T3OnMap(map);
            return DefDatabase<PawnKindDef>.AllDefsListForReading.Where(k => Eligible(k, map, t3)).TryRandomElement(out kind);
        }

        /// <summary>The herd-migration route: an entry cell and the reachable edge cell farthest from it.</summary>
        public static bool TryFindStartAndEnd(Map map, out IntVec3 start, out IntVec3 end)
        {
            end = IntVec3.Invalid;
            if (!RCellFinder.TryFindRandomPawnEntryCell(out start, map, CellFinder.EdgeRoadChance_Animal)) return false;
            IntVec3 s = start;
            for (int i = 0; i < 8; i++)
            {
                if (!CellFinder.TryFindRandomEdgeCellWith(x => map.reachability.CanReach(s, x, PathEndMode.OnCell,
                        TraverseParms.For(TraverseMode.PassDoors)), map, CellFinder.EdgeRoadChance_Ignore, out IntVec3 r)) break;
                if (!end.IsValid || r.DistanceToSquared(start) > end.DistanceToSquared(start)) end = r;
            }
            return end.IsValid;
        }

        public static string EdgeName(Map map, IntVec3 c)
        {
            int dx = Mathf.Min(c.x, map.Size.x - 1 - c.x), dz = Mathf.Min(c.z, map.Size.z - 1 - c.z);
            if (dx < dz) return (c.x < map.Size.x / 2 ? "RM_TitanPassage_West" : "RM_TitanPassage_East").Translate();
            return (c.z < map.Size.z / 2 ? "RM_TitanPassage_South" : "RM_TitanPassage_North").Translate();
        }
    }

    /// <summary>The scheduled passages of one map: tremors through the warning, then the titan walks in.</summary>
    public class MapComponent_TitanPassages : MapComponent
    {
        private const int ShakeInterval = 300;
        private const int MessageInterval = 2 * GenDate.TicksPerHour;

        private PawnKindDef kind;
        private IntVec3 start = IntVec3.Invalid, end = IntVec3.Invalid;
        private int arrivalTick = -1, warnedTick = -1, warningTicks;
        private Pawn arrived;

        public MapComponent_TitanPassages(Map map) : base(map) { }

        public bool HasPending => kind != null && arrivalTick >= 0;
        public PawnKindDef PendingKind => kind;
        public int ArrivalTick => arrivalTick;
        public Pawn LastArrived => arrived;

        public void Schedule(PawnKindDef k, IntVec3 s, IntVec3 e, int warning)
        {
            kind = k; start = s; end = e; warningTicks = warning;
            int now = Find.TickManager.TicksGame;
            arrivalTick = now + warning; warnedTick = now;
        }

        /// <summary>Validation hook: bring the arrival forward to the next tick.</summary>
        public void DebugArriveNow() { if (HasPending) arrivalTick = Find.TickManager.TicksGame; }

        public override void MapComponentTick()
        {
            if (!HasPending) return;
            int now = Find.TickManager.TicksGame;
            if (now >= arrivalTick) { Arrive(); return; }
            if (now % ShakeInterval == 0 && Find.CurrentMap == map)
            {
                // Footfall: stronger the nearer it comes (0.3 at the first tremor, 1.5 at arrival).
                float progress = warningTicks > 0 ? 1f - (arrivalTick - now) / (float)warningTicks : 1f;
                Find.CameraDriver.shaker.DoShake(Mathf.Lerp(0.3f, 1.5f, Mathf.Clamp01(progress)));
            }
            if (now - warnedTick >= MessageInterval)
            {
                warnedTick = now;
                Messages.Message("RM_TitanPassage_TremorStronger".Translate(), new TargetInfo(start, map), MessageTypeDefOf.NeutralEvent);
            }
        }

        private void Arrive()
        {
            PawnKindDef k = kind;
            IntVec3 s = start, e = end;
            Clear();
            // the warned edge is kept while it is still standable and reaches the far edge; otherwise a fresh route is found
            bool routeOk = s.IsValid && e.IsValid && s.InBounds(map) && s.Standable(map)
                           && map.reachability.CanReach(s, e, PathEndMode.OnCell, TraverseParms.For(TraverseMode.PassDoors));
            if (!routeOk) routeOk = TitanPassageUtility.TryFindStartAndEnd(map, out s, out e);
            if (!RM_HugeThingsSettings.TitanEventsActive || !TitanPassageUtility.Eligible(k, map, TitanPassageUtility.T3OnMap(map)) || !routeOk)
            {
                Messages.Message("RM_TitanPassage_Faded".Translate(), MessageTypeDefOf.NeutralEvent);
                return;
            }
            Pawn titan = PawnGenerator.GeneratePawn(new PawnGenerationRequest(k, null, PawnGenerationContext.NonPlayer, map.Tile));
            GenSpawn.Spawn(titan, CellFinder.RandomClosewalkCellNear(s, map, 8), map, Rot4.FromAngleFlat((map.Center - s).AngleFlat));
            LordMaker.MakeNewLord(null, new LordJob_ExitMapNear(e, LocomotionUrgency.Walk), map, new List<Pawn> { titan });
            arrived = titan;
            Find.LetterStack.ReceiveLetter("RM_TitanPassage_ArriveLabel".Translate(titan.LabelShortCap),
                "RM_TitanPassage_ArriveText".Translate(titan.LabelShort), LetterDefOf.ThreatSmall, titan);
        }

        private void Clear()
        {
            kind = null; arrivalTick = -1; warnedTick = -1; start = IntVec3.Invalid; end = IntVec3.Invalid;
        }

        public override void ExposeData()
        {
            base.ExposeData();
            Scribe_Defs.Look(ref kind, "rmTitanKind");
            Scribe_Values.Look(ref start, "rmTitanStart", IntVec3.Invalid);
            Scribe_Values.Look(ref end, "rmTitanEnd", IntVec3.Invalid);
            Scribe_Values.Look(ref arrivalTick, "rmTitanArrival", -1);
            Scribe_Values.Look(ref warnedTick, "rmTitanWarned", -1);
            Scribe_Values.Look(ref warningTicks, "rmTitanWarningTicks", 0);
            Scribe_References.Look(ref arrived, "rmTitanArrived");
            if (Scribe.mode == LoadSaveMode.PostLoadInit && kind == null) arrivalTick = -1;
        }
    }
}
// Verse-free kernel of Titanic Creatures: the size-tier ladder, the force-in/force-out override, the Large Pawns footprint size, the
// sub-linear butcher yield, the crush decision and damage, the roof rule, and the T3 corpse-site pool arithmetic (daily spoilage and
// per-session harvest). TitanicTierUtility, YieldCurveUtility, CrushTableUtility, TitanicWakeProcessor, LargePawnsBridge and
// Building_TitanicCorpseSite call these with the same expressions; SelfTest/TitanicFuzz.cs compiles this file alone.
// Keep it free of Verse/RimWorld/UnityEngine/HarmonyLib (a `using Verse;` here breaks the self-test build, which is the guard rail).
// Tiers are ints (None 0, T1 1, T2 2, T3 3) so they order with the same comparisons the enum TitanicTier gives.
using System;
using System.Collections.Generic;

namespace RimMandrake.TitanicCreatures
{
    public static class RM_TitanicKernel
    {
        public const int None = 0, T1 = 1, T2 = 2, T3 = 3;
        /// <summary>RM_TitanicExtension.forceEnabled: unset (auto), true (force in), false (force out).</summary>
        public const int ForceAuto = 0, ForceIn = 1, ForceOut = -1;

        // PROVISIONAL (BENCH draft, not owner-ruled): crush damage per pass, before the player's multiplier.
        public const float CrushDamageLight = 20f;
        public const float CrushDamageHeavy = 60f;
        public const int TicksPerDay = 60000;

        /// <summary>The player-facing tier ladder is only meaningful when 0 &lt; T1 &lt; T2 &lt; T3.</summary>
        public static bool ThresholdsValid(float t1, float t2, float t3)
        {
            // B3.19 / C3.6 / D3.3: an infinite or NaN rung is never a ladder (NaN fails every comparison already; inf T3 did not).
            return Finite(t1) && Finite(t2) && Finite(t3) && t1 > 0f && t1 < t2 && t2 < t3;
        }

        public static bool Finite(float v) => !float.IsNaN(v) && !float.IsInfinity(v);

        /// <summary>HUGETHINGS_SETTINGS_HARDENING_1 (B3.19): a Scribe-loaded or edited float setting, forced finite and into its slider
        /// range; a NaN/infinite value falls back to the shipped default (itself clamped, so a bad default cannot escape either).</summary>
        public static float SaneSetting(float v, float min, float max, float fallback)
        {
            if (!Finite(v)) v = fallback;
            if (!Finite(v)) v = min;
            return Clamp(v, min, max);
        }

        /// <summary>Integer setting into its slider range.</summary>
        public static int SaneSetting(int v, int min, int max)
        {
            return v < min ? min : (v > max ? max : v);
        }

        /// <summary>Def-level: could any pawn of this race ever be tiered (decides the comp auto-attach).</summary>
        public static bool DefQualifies(float baseBodySize, float t1, int force)
        {
            if (force == ForceOut) return false;
            if (force == ForceIn) return true;
            return baseBodySize >= t1;
        }

        /// <summary>TITAN_WAKE_FIXES_1 (B3.18 / C3.4): Pawn.BodySize is lifestage.bodySizeFactor x baseBodySize, so a race qualifies on its
        /// base times the LARGEST factor any of its life stages reaches (a factor below 1 never shrinks the test below the base).</summary>
        public static bool DefQualifies(float baseBodySize, float maxLifeStageFactor, float t1, int force)
        {
            float f = Finite(maxLifeStageFactor) && maxLifeStageFactor > 1f ? maxLifeStageFactor : 1f;
            return DefQualifies(baseBodySize * f, t1, force);
        }

        /// <summary>Maximum supported factor for spacing; NaN means no trustworthy complete stage list. A missing/null stage
        /// is passed as NaN by the Verse adapter. Malformed data must retain AdultTier spacing rather than relaxing it.</summary>
        public static float MaxSupportedLifeStageFactor(IEnumerable<float> factors)
        {
            if (factors == null) return float.NaN;
            float max = 0f;
            foreach (float factor in factors)
            {
                if (!Finite(factor) || factor <= 0f) return float.NaN;
                if (factor > max) max = factor;
            }
            return max > 0f ? max : float.NaN;
        }

        /// <summary>TITAN_WAKE_FIXES_1 (B3.6): a multi-cell thing is registered in every cell it covers, so a footprint scan sees it once per
        /// covered cell. Each thing comes back once, in first-seen order, so one titan step strikes it once.</summary>
        public static List<T> UniqueInOrder<T>(IEnumerable<IEnumerable<T>> cells) where T : class
        {
            var seen = new HashSet<T>();
            var outList = new List<T>();
            foreach (IEnumerable<T> cell in cells)
            {
                if (cell == null) continue;
                foreach (T t in cell)
                    if (t != null && seen.Add(t)) outList.Add(t);
            }
            return outList;
        }

        /// <summary>Runtime tier of one pawn: bodySize ladder, force-out wins, force-in floors at T1.</summary>
        public static int TierFor(float bodySize, float t1, float t2, float t3, int force)
        {
            if (force == ForceOut) return None;
            int tier;
            if (bodySize >= t3) tier = T3;
            else if (bodySize >= t2) tier = T2;
            else if (bodySize >= t1) tier = T1;
            else tier = None;
            if (tier == None && force == ForceIn) tier = T1;
            return tier;
        }

        /// <summary>Tier a body size would reach if it qualified at all (never None): what the Large Pawns footprint is projected from.</summary>
        public static int QualifiedTier(float bodySize, float t2, float t3)
        {
            if (bodySize >= t3) return T3;
            if (bodySize >= t2) return T2;
            return T1;
        }

        /// <summary>Large Pawns footprint edge for a tier (its hard ceiling is 4).</summary>
        public static int FootprintSize(int tier)
        {
            switch (tier)
            {
                case T3: return 4;
                case T2: return 3;
                default: return 2;
            }
        }

        /// <summary>The Large Pawns size-override row for a def that carries an RM_TitanicExtension with forceEnabled set (force-in always qualifies;
        /// a force-in race below the T1 floor is T1).</summary>
        public static int OverrideFootprint(float baseBodySize, float t1, float t2, float t3, int force)
        {
            if (force == ForceOut) return 1;
            return FootprintSize(QualifiedTier(baseBodySize, t2, t3));
        }

        /// <summary>Unity Mathf.Clamp semantics (min wins when min &gt; max).</summary>
        public static float Clamp(float v, float min, float max)
        {
            if (v < min) v = min;
            else if (v > max) v = max;
            return v;
        }

        /// <summary>Yield multiplier for a T1/T2 corpse: sqrt(floor / bodySize), kept in [minFactor, 1].</summary>
        public static float SubLinearFactor(float bodySize, float floor, float minFactor)
        {
            float b = Math.Max(bodySize, floor);
            return Clamp((float)Math.Sqrt(floor / b), minFactor, 1f);
        }

        /// <summary>The tier floor the yield curve measures against (T1 floor for T1, else T2's).</summary>
        public static float YieldFloor(int tier, float t1, float t2)
        {
            return tier == T1 ? t1 : t2;
        }

        /// <summary>One crush-table row against a tier: unlisted things never reach here (they are protected by default).</summary>
        public static bool CrushAllowed(int tier, bool crushable, int minTier)
        {
            return tier != None && crushable && tier >= minTier;
        }

        /// <summary>Crush damage per pass for a non-destroyed crushable. A bigger tier never hits softer than a smaller one.</summary>
        public static float CrushDamage(int tier, float multiplier)
        {
            return (tier >= T2 ? CrushDamageHeavy : CrushDamageLight) * multiplier;
        }

        /// <summary>T3 destroys a crushable Building outright; everything else crushable takes damage.</summary>
        public static bool DestroysOutright(int tier, bool isBuilding)
        {
            return tier == T3 && isBuilding;
        }

        /// <summary>Thin roofs are holed from T2; a thick roof (overhead mountain) is never removed.</summary>
        public static bool HolesRoof(int tier, bool hasRoof, bool thick)
        {
            return tier >= T2 && hasRoof && !thick;
        }

        /// <summary>Rubble trail: every tiered pawn leaves a chance of filth per cell.</summary>
        public static bool LeavesFilth(int tier, bool rolledUnderChance)
        {
            return tier >= T1 && rolledUnderChance;
        }

        /// <summary>Units lost to one day of spoilage: a fixed fraction of what is left, always at least one while anything is left.</summary>
        public static int SpoilLoss(int remaining, float perDay)
        {
            if (remaining <= 0) return 0;
            int loss = (int)Math.Ceiling(remaining * perDay);
            return Math.Min(remaining, Math.Max(0, loss));
        }

        /// <summary>Units one work session pulls from the pool.</summary>
        public static int HarvestTake(int remaining, int perSession)
        {
            return Math.Max(0, Math.Min(remaining, perSession));
        }

        // --- TITAN_CAMPS_SCAVENGERS_EVENTS_1 (cards #4 and #5, owner 2026-09-09) ------------------------------------------------

        /// <summary>Units a site's visitors (drawn scavengers, a camp's people) eat or carry off in one day: each takes up to
        /// perVisitorPerDay, never more than is left, never negative (long arithmetic, so a huge setting cannot overflow).</summary>
        public static int VisitorTake(int remaining, int visitors, int perVisitorPerDay)
        {
            if (remaining <= 0 || visitors <= 0 || perVisitorPerDay <= 0) return 0;
            long want = (long)visitors * perVisitorPerDay;
            return (int)Math.Min(remaining, want);
        }

        /// <summary>How many scavengers one draw brings: at least one while meat is left, at most `max`, and never more than the
        /// meat left can feed for a day (a nearly picked-clean site draws one, not a pack).</summary>
        public static int ScavengerCount(int meatRemaining, int perVisitorPerDay, int max)
        {
            if (meatRemaining <= 0 || max <= 0) return 0;
            int per = Math.Max(1, perVisitorPerDay);
            long need = ((long)meatRemaining + per - 1) / per;
            return (int)Math.Max(1, Math.Min(max, need));
        }

        /// <summary>TITAN_PASSAGE_PRUNE_WHALES_ON_FOOT (owner, by card 2026-10-21): "Calves are ok. Sea creatures are not on dry
        /// land. Opposite can happen in sea biomes. Only sea creatures not land creatures. Every biome should have something like
        /// this. ... A few exceptions such as rust cathedral and dark side biomes. Only if giants can exist there. Should draw
        /// from the hints of their own biome always of course." A race may walk (or swim) in as a footfall-warned titan passage
        /// only when: the map's biome has not opted out; it is a titan by its ADULT tier (T2 or T3, so a calf kind of a titan
        /// race qualifies); its water-ness matches the map's (sea giants only on a sea map, land giants only on land); it comes
        /// from the map biome's own hints, which are the biome's passage list when it has one and its own roster otherwise; the
        /// season suits it; and (spacing law, one T3 per map) no T3 already stands on the map when any supported stage can be T3.</summary>
        public static bool TitanEventEligible(int adultTier, bool biomeOptedOut, bool seaCreature, bool seaMap,
            bool biomeHasPassageList, bool onPassageList, bool homedHere, bool seasonOk, bool t3OnMap)
        {
            // Compatibility for callers that only know a conservative lineage tier.
            return TitanEventEligible(adultTier, adultTier, biomeOptedOut, seaCreature, seaMap,
                biomeHasPassageList, onPassageList, homedHere, seasonOk, t3OnMap);
        }

        /// <summary>Lineage decides eligibility (calves stay); supported stages decide T3 spacing. No pool or habitat gate changes.</summary>
        public static bool TitanEventEligible(int adultTier, int spacingTier, bool biomeOptedOut, bool seaCreature, bool seaMap,
            bool biomeHasPassageList, bool onPassageList, bool homedHere, bool seasonOk, bool t3OnMap)
        {
            if (biomeOptedOut || adultTier < T2 || seaCreature != seaMap || !seasonOk) return false;
            if (!(biomeHasPassageList ? onPassageList : homedHere)) return false;
            return !(spacingTier == T3 && t3OnMap);
        }

        /// <summary>A sea creature is a race homed in at least one biome, every one of them a sea biome. A race homed nowhere is
        /// not a sea creature (and is never drawn: no biome hints it).</summary>
        public static bool IsSeaCreature(int seaHomes, int landHomes) => seaHomes > 0 && landHomes == 0;

        /// <summary>The footfall warning before a titan arrives, in ticks: the setting's hours (2500 ticks each), never below a
        /// quarter hour, so the tremors always come first, never above three days. The hours are clamped BEFORE the cast: an
        /// out-of-range double-to-long cast is unspecified (Mono gives long.MinValue, which read as the quarter-hour floor).</summary>
        public static int WarningTicks(float hours)
        {
            double h = Finite(hours) ? Math.Max(0.0, Math.Min(hours, 72.0)) : 0.0;
            long t = (long)Math.Round(h * 2500.0);
            return (int)Math.Max(625L, Math.Min(t, 60000L * 3));
        }

        /// <summary>
        /// TITAN_ROOF_AVOIDANCE_1 (B3.5 / D3.1 / D1.4): the anchor cells a titan's route must not use, because its footprint there
        /// (anchor + [offMinX..offMaxX] x [offMinZ..offMaxZ]) would overlap a thick-roofed cell. thick[i] is cell i = z*w + x of a
        /// w x h map. Every anchor within the footprint's reach of a thick cell is marked once in `outMark`.
        /// </summary>
        public static void MarkRoofExcluded(int w, int h, bool[] thick, int offMinX, int offMinZ, int offMaxX, int offMaxZ, bool[] outMark)
        {
            for (int i = 0; i < thick.Length; i++)
            {
                if (!thick[i]) continue;
                int x = i % w, z = i / w;
                // anchor a covers x when a.x + offMinX <= x <= a.x + offMaxX
                int ax0 = Math.Max(0, x - offMaxX), ax1 = Math.Min(w - 1, x - offMinX);
                int az0 = Math.Max(0, z - offMaxZ), az1 = Math.Min(h - 1, z - offMinZ);
                for (int az = az0; az <= az1; az++)
                    for (int ax = ax0; ax <= ax1; ax++)
                        outMark[az * w + ax] = true;
            }
        }
    }
